<!doctype html><html><head><meta charset="utf-8"><title>LSP Sales Report</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:DejaVu Sans,Arial;font-size:9px;color:#172033}h1{margin:0;font-size:20px}.meta{margin:6px 0 14px;color:#64748b}.summary{margin-bottom:12px}.summary span{display:inline-block;margin-right:20px;padding:7px 10px;border:1px solid #dbe2ea}.table{width:100%;border-collapse:collapse;table-layout:fixed}.table th,.table td{box-sizing:border-box;vertical-align:middle;overflow-wrap:anywhere}.table th:nth-child(1),.table td:nth-child(1){width:4%}.table th:nth-child(2),.table td:nth-child(2){width:8%}.table th:nth-child(3),.table td:nth-child(3){width:9%}.table th:nth-child(4),.table td:nth-child(4){width:23%}.table th:nth-child(5),.table td:nth-child(5){width:14%}.table th:nth-child(6),.table td:nth-child(6){width:7%}.table th:nth-child(7),.table td:nth-child(7){width:8%}.table th:nth-child(8),.table td:nth-child(8){width:5%}.table th:nth-child(9),.table td:nth-child(9){width:7%}.table th:nth-child(10),.table td:nth-child(10){width:7%}.table th:nth-child(11),.table td:nth-child(11){width:4%}.table th:nth-child(12),.table td:nth-child(12){width:4%}.table th{background:#159176;color:#fff;padding:7px 5px;text-align:left;font-size:8px}.table td{padding:6px 5px;border-bottom:1px solid #e5eaf0;vertical-align:top}.table tr:nth-child(even) td{background:#f8fafc}.right{text-align:right}.table th:nth-child(n+8){text-align:right}</style></head><body><h1>LSP Sales Report</h1><div class="meta">Period: {{ $startDate }} to {{ $endDate }}</div><div class="summary"><span>Total Sales: {{ $allSales->count() }}</span><span>Amount: {{ number_format($allSales->sum('total_amount'),2) }} BDT</span><span>Paid: {{ number_format($allSales->sum('paid_amount'),2) }} BDT</span><span>Due: {{ number_format($allSales->sum('due_amount'),2) }} BDT</span></div><table class="table"><colgroup><col style="width:4%"><col style="width:8%"><col style="width:9%"><col style="width:23%"><col style="width:14%"><col style="width:7%"><col style="width:8%"><col style="width:5%"><col style="width:7%"><col style="width:7%"><col style="width:4%"><col style="width:4%"></colgroup><thead><tr><th>SL</th><th>Date</th><th>Invoice</th><th>Products</th><th>Customer</th><th>Sell By</th><th>Area Office</th><th class="right">Qty</th><th class="right">Total</th><th class="right">Paid</th><th class="right">Due</th><th class="right">Profit</th></tr></thead><tbody>@forelse($allSales as $sale)<tr><td>{{ $loop->iteration }}</td><td>{{ $sale->sale_date }}</td><td>{{ $sale->invoice_no }}</td><td>{{ $sale->items->pluck('product.product_name')->filter()->implode(', ') }}</td><td>{{ $sale->customer_name ?: '-' }}<br><small>{{ $sale->customer_phone }}</small></td><td>{{ $sale->salesman?->name ?: 'Area Office' }}</td><td>{{ $sale->warehouse?->name ?: $sale->salesman?->warehouse?->name ?: '-' }}</td><td class="right">{{ number_format($sale->items->sum('quantity'),2) }}</td><td class="right">{{ number_format($sale->total_amount,2) }}</td><td class="right">{{ number_format($sale->paid_amount,2) }}</td><td class="right">{{ number_format($sale->due_amount,2) }}</td><td class="right">{{ number_format($sale->profit_amount,2) }}</td></tr>@empty<tr><td colspan="12">No LSP sales found.</td></tr>@endforelse</tbody></table></body></html>



